def hash_file(file_path: Path, algorithm: str = 'sha256') -> str:
    hasher = hashlib.new(algorithm)
    with open(file_path, 'rb') as f:
        for chunk in iter(lambda: f.read(8192), b''):
            hasher.update(chunk)
    return f"{algorithm}:{hasher.hexdigest()}"
